# filename: app/api/v1/endpoints/events.py
# Code Generated by Sidekick is for learning and experimentation purposes only.

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session
from sqlalchemy import func
from typing import List
import uuid

from app.database import get_db
from app.schemas.event import (
    EventCreate,
    EventUpdate,
    EventResponse,
    EventWithSeats,
    EventListResponse
)
from app.models.event import Event
from app.models.seat import Seat, SeatStatus
from app.core.logging import get_logger

logger = get_logger(__name__)
router = APIRouter()


@router.post(
    "/",
    response_model=EventResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Create event",
    description="Create a new event"
)
async def create_event(
        event: EventCreate,
        db: Session = Depends(get_db)
):
    """
    Create a new event.

    This only creates the event record. Seats must be added separately.
    """
    db_event = Event(**event.model_dump())

    try:
        db.add(db_event)
        db.commit()
        db.refresh(db_event)

        logger.info(f"Event created: {db_event.event_id}")
        return db_event

    except Exception as e:
        db.rollback()
        logger.error(f"Failed to create event: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Failed to create event"
        )


@router.get(
    "/",
    response_model=EventListResponse,
    summary="List events",
    description="Get list of all events with pagination"
)
async def list_events(
        skip: int = Query(0, ge=0),
        limit: int = Query(100, ge=1, le=1000),
        db: Session = Depends(get_db)
):
    """
    Get paginated list of all events.
    """
    total = db.query(func.count(Event.event_id)).scalar()

    events = db.query(Event).order_by(
        Event.event_date.desc()
    ).offset(skip).limit(limit).all()

    return EventListResponse(
        events=events,
        total=total,
        page=skip // limit + 1,
        page_size=limit
    )


@router.get(
    "/{event_id}",
    response_model=EventWithSeats,
    summary="Get event details",
    description="Get detailed information about an event including seat statistics"
)
async def get_event(
        event_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Get event details with seat availability statistics.
    """
    event = db.query(Event).filter(Event.event_id == event_id).first()

    if not event:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Event not found"
        )

    # Calculate seat statistics
    seat_stats = db.query(
        Seat.status,
        func.count(Seat.seat_id)
    ).filter(
        Seat.event_id == event_id
    ).group_by(Seat.status).all()

    stats_dict = dict(seat_stats)

    return EventWithSeats(
        event_id=event.event_id,
        event_name=event.event_name,
        event_date=event.event_date,
        venue=event.venue,
        total_seats=event.total_seats,
        created_at=event.created_at,
        updated_at=event.updated_at,
        available_seats=stats_dict.get(SeatStatus.AVAILABLE, 0),
        booked_seats=stats_dict.get(SeatStatus.BOOKED, 0),
        reserved_seats=stats_dict.get(SeatStatus.RESERVED, 0)
    )


@router.put(
    "/{event_id}",
    response_model=EventResponse,
    summary="Update event",
    description="Update event details"
)
async def update_event(
        event_id: uuid.UUID,
        event_update: EventUpdate,
        db: Session = Depends(get_db)
):
    """
    Update event details.
    """
    event = db.query(Event).filter(Event.event_id == event_id).first()

    if not event:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Event not found"
        )

    try:
        update_data = event_update.model_dump(exclude_unset=True)

        for field, value in update_data.items():
            setattr(event, field, value)

        db.commit()
        db.refresh(event)

        logger.info(f"Event updated: {event_id}")
        return event

    except Exception as e:
        db.rollback()
        logger.error(f"Failed to update event: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Failed to update event"
        )


@router.delete(
    "/{event_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    summary="Delete event",
    description="Delete an event and all associated seats"
)
async def delete_event(
        event_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Delete an event. This will cascade delete all seats and bookings.
    """
    event = db.query(Event).filter(Event.event_id == event_id).first()

    if not event:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Event not found"
        )

    try:
        db.delete(event)
        db.commit()
        logger.info(f"Event deleted: {event_id}")

    except Exception as e:
        db.rollback()
        logger.error(f"Failed to delete event: {e}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Failed to delete event"
        )
